// Validate input data from webhook
  const items = $input.all();

  for (const item of items) {
    const data = item.json.body; // Access the body property

    // Validate user.id is UUID
    if (!data.user || !data.user.id) {
      throw new Error('user.id is required');
    }

    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(data.user.id)) {
      throw new Error('user.id must be a valid UUID');
    }

    // Validate user.email is valid email
    if (!data.user.email) {
      throw new Error('user.email is required');
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(data.user.email)) {
      throw new Error('user.email must be a valid email address');
    }

    // Validate context.existing_goals is array
    if (!data.context || !Array.isArray(data.context.existing_goals)) {
      throw new Error('context.existing_goals must be an array');
    }

    // Validate context.request_params.suggestion_count is less than or equal to 10
    if (data.context && data.context.request_params && data.context.request_params.suggestion_count !== undefined) {
      if (typeof data.context.request_params.suggestion_count !== 'number') {
        throw new Error('context.request_params.suggestion_count must be a number');
      }
      if (data.context.request_params.suggestion_count > 10) {
        throw new Error('context.request_params.suggestion_count must be less than or equal to 10');
      }
    }
  }

  // Return items with the body data extracted for easier access in next nodes
  return items.map(item => ({
    json: item.json.body
  }));

// Build AI Prompt for Goal Suggestions
// This code constructs a comprehensive prompt for the AI agent
// using user profile data, existing goals, and request parameters

const items = $input.all();
const inputData = items[0].json;

// Extract user information
const user = inputData.user || {};
const userId = user.id || 'unknown';
const userEmail = user.email || 'unknown';
const userName = user.metadata?.name || 'User';
const userPreferences = user.metadata?.preferences || {};

// Extract context information
const context = inputData.context || {};
const existingGoals = context.existing_goals || [];
const completedGoalsCount = context.completed_goals_count || 0;
const activeGoalsCount = context.active_goals_count || 0;
const averageCompletionRate = context.average_completion_rate || 0;
const mostActiveCategories = context.most_active_categories || [];

// Build existing goals summary
const goalSummary = existingGoals.length > 0 
  ? existingGoals.map(g => `- ${g.title || g.name}: ${g.description || 'No description'} (Status: ${g.status || 'unknown'})`).join('\n')
  : 'No existing goals';

// Extract request parameters
const requestParams = context.request_params || {};
const category = requestParams.category || 'general';
const timeframe = requestParams.timeframe || 'short-term';
const numberOfSuggestions = requestParams.suggestion_count || 5;
const focusArea = requestParams.focus_area || '';
const difficulty = requestParams.difficulty || '';

// Build the AI prompt
const prompt = `You are an intelligent goal-setting assistant. Based on the user's profile and existing goals, suggest ${numberOfSuggestions} personalized, actionable goals.

User Information:
- User ID: ${userId}
- Name: ${userName}
- Email: ${userEmail}
- Preferences: ${JSON.stringify(userPreferences, null, 2)}

User Statistics:
- Completed Goals: ${completedGoalsCount}
- Active Goals: ${activeGoalsCount}
- Average Completion Rate: ${(averageCompletionRate * 100).toFixed(1)}%
- Most Active Categories: ${mostActiveCategories.join(', ') || 'Not specified'}

Existing Goals:
${goalSummary}

Request Parameters:
- Category: ${category}
- Timeframe: ${timeframe}
- Focus Area: ${focusArea || 'Not specified'}
- Difficulty: ${difficulty || 'Not specified'}

Please suggest ${numberOfSuggestions} new goals that:
1. Align with the user's preferences and past performance
2. Complement (not duplicate) their existing goals
3. Are appropriate for the ${timeframe} timeframe
4. Fall within the ${category} category
${focusArea ? `5. Focus on: ${focusArea}` : ''}
${difficulty ? `6. Match difficulty level: ${difficulty}` : ''}
7. Consider their ${(averageCompletionRate * 100).toFixed(1)}% completion rate when setting difficulty
8. Build on their most active categories: ${mostActiveCategories.join(', ')}

For each goal, provide:
- A clear, motivating title
- A detailed description
- Specific, measurable success criteria
- Estimated time to complete
- Difficulty level (beginner, intermediate, advanced)
- Relevant tags or categories
- Explanation of why this goal is suggested for this specific user`;

// Return the prompt and metadata
return [
  {
    json: {
      prompt: prompt,
      userId: userId,
      userName: userName,
      userEmail: userEmail,
      category: category,
      timeframe: timeframe,
      numberOfSuggestions: numberOfSuggestions,
      focusArea: focusArea,
      difficulty: difficulty,
      existingGoalsCount: existingGoals.length,
      completedGoalsCount: completedGoalsCount,
      activeGoalsCount: activeGoalsCount,
      averageCompletionRate: averageCompletionRate,
      mostActiveCategories: mostActiveCategories,
      timestamp: new Date().toISOString()
    }
  }
];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "goal_suggestions": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier for the goal suggestion"
          },
          "title": {
            "type": "string",
            "description": "Title of the suggested goal"
          },
          "description": {
            "type": "string",
            "description": "Detailed description of the goal"
          },
          "category": {
            "type": "string",
            "description": "Category of the goal (e.g., health, career, personal development)"
          },
          "difficulty": {
            "type": "string",
            "description": "Difficulty level of the goal (e.g., easy, medium, hard)"
          },
          "estimated_duration_days": {
            "type": "number",
            "description": "Estimated number of days to complete the goal"
          },
          "why_suggested": {
            "type": "string",
            "description": "Explanation of why this goal is suggested for the user"
          },
          "milestones": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "List of milestones to achieve the goal"
          }
        },
        "required": ["id", "title", "description", "category", "difficulty", "estimated_duration_days", "why_suggested", "milestones"]
      }
    }
  },
  "required": ["goal_suggestions"]
}
